import json
from pathlib import Path
p=Path(__file__).parent/'codes/root/high_stakes.jsonl'
rows=[json.loads(l) for l in p.read_text().splitlines()]
rows[4]['quality']='I'
p.write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rows))
